    const c = document.createElement('canvas'); c.width = c.height = 128; const g2 = c.getContext('2d');
    g2.fillStyle = '#ffffff'; g2.beginPath(); g2.arc(64, 64, 58, 0, 7); g2.fill(); g2.lineWidth = 9; g2.strokeStyle = BASE[ch]; g2.stroke();
    g2.fillStyle = '#141820'; g2.font = '800 74px system-ui, sans-serif'; g2.textAlign = 'center'; g2.textBaseline = 'middle'; g2.fillText(ch, 64, 69);
