const sphGeo = new THREE.SphereGeometry(1, 28, 20);
const unitCyl = new THREE.CylinderGeometry(1, 1, 1, 10, 1, true);
const hexGeo = new THREE.CylinderGeometry(.19, .19, .09, 6);

function tube(pts, r, mat, rs = 8, segs = null, closed = false) {
  const c = new THREE.CatmullRomCurve3(pts, closed);
  return new THREE.Mesh(new THREE.TubeGeometry(c, segs ?? Math.max(12, pts.length * 6), r, rs, closed), mat);
}
function sphere(r, mat, seg = 28) { const m = new THREE.Mesh(seg === 28 ? sphGeo : new THREE.SphereGeometry(1, seg, Math.round(seg * .7)), mat); m.scale.setScalar(r); return m; }
