function cylM(a, b, r) { const d = b.clone().sub(a); return M4(a.clone().addScaledVector(d, .5), qFromTo(UP, d), V(r, d.length(), r)); }
function stick(a, b, r, mat) { const m = new THREE.Mesh(unitCyl, mat); m.applyMatrix4(cylM(a, b, r)); return m; }
