  for (let k = 0; k < steps; k++) { d.add(randDir().multiplyScalar(.8)).normalize(); const q = p.clone().addScaledVector(d, len); if (keep && !keep(q)) { d.negate(); continue; } p = q; pts.push(p.clone()); }
