  const erTub = xray(C.er, 1, 1.1, .08);
  for (let i = 0; i < 16; i++) g.add(tube(walk(V(rr(-3.5, 2.5), rr(-7.8, -5.6), rr(-2.5, 3.5)), 21, .35), rr(.06, .11), erTub, 6));
  mk = tagFrom(g, mk, 'rough-er');

  cloud(g, 2600, () => randDir().multiplyScalar(NR + rr(.5, 2.8)).add(NUC), C.dots, .07, .22);
  cloud(g, 3500, () => { let v; do { v = randDir().multiplyScalar(R * Math.cbrt(rand()) * .96); } while (v.distanceTo(NUC) < NR + 2.6); return v; }, C.dots, .06, .16);
  an.push(A(NUC.clone().add(V(.85, -.35, .45).normalize().multiplyScalar(NR + 2.5)), 'Ribosomes', 'ribosome'));
  mk = tagFrom(g, mk, 'ribosome');

  {
    const golgi = partModel('golgi').group; golgi.scale.setScalar(.38);
    golgi.position.copy(spot(3.4, 6.4, 6.8)); golgi.lookAt(NUC); golgi.rotateX(Math.PI / 2);
    g.add(golgi);
    an.push(A(golgi.position, 'Golgi apparatus', 'golgi'));
  }
