  // the same mitochondrion model as its own level, scaled down (clones share geometry and materials)
  const mitoProto = makeMitochondrion().group, mitos = [];
  for (let i = 0; i < 11; i++) {
    const sc = rr(.28, .38), sy = sc * rr(.85, 1.15), m = mitoProto.clone(); m.scale.set(sc, sy, sc);
    m.position.copy(spot(4 * sy)); m.rotation.set(rr(0, 6.3), rr(0, 6.3), rr(0, 6.3)); g.add(m); mitos.push(m.position);
  }
