  const prof = r => { const pts = []; for (let i = 0; i <= 12; i++) { const a = -Math.PI / 2 + i / 12 * Math.PI / 2; pts.push(new THREE.Vector2(Math.max(r * Math.cos(a), .001), -L + r * Math.sin(a))); } for (let i = 12; i >= 0; i--) { const a = Math.PI / 2 - i / 12 * Math.PI / 2; pts.push(new THREE.Vector2(Math.max(r * Math.cos(a), .001), L + r * Math.sin(a))); } return pts; };
