    const s = k % 2 ? 1 : -1, a = R * .6, x0 = s * (R - .22 - a), c = .86 * Math.sqrt(Math.max(.01, R * R - x0 * x0)), th = .11;
    const geo = displace(new THREE.SphereGeometry(1, 48, 16), .05, 2, k * 3.1, 3); geo.scale(a, th, c);
    const m = new THREE.Mesh(geo, cm); m.position.set(x0, y, 0); g.add(m);
    const jx0 = x0 + s * a * .96, jx1 = s * (R + .04), neck = new THREE.Mesh(new THREE.CylinderGeometry(.085, .085, 1, 12, 1, true), jm);
    neck.position.set((jx0 + jx1) / 2, y, 0); neck.rotation.z = Math.PI / 2; neck.scale.y = Math.abs(jx1 - jx0) + .06; g.add(neck);
    cr.push({ y, x0, a, c, th, jx: (jx0 + jx1) / 2 });
