  cloud(g, 700, () => { let v; do { v = V(rr(-1.3, 1.3), rr(-3.4, 3.4), rr(-1.3, 1.3)); } while (Math.hypot(v.x, v.z) > rAt(v.y) * .9); return v; }, '#fff2b0', .05, .35);
  const dnas = []; for (let i = 0; i < 3; i++) { const k = new THREE.Mesh(new THREE.TorusKnotGeometry(.16, .022, 64, 8, 2, 3), std('#7fd8ff', { glow: .5 })); k.position.set(rr(-.4, .4), -1.95 + i * 1.95, rr(.3, .7)); g.add(k); dnas.push(k.position.clone()); }
  const mr = []; for (let i = 0; i < 40; i++) { const k = Math.floor(rand() * (cr.length - 1)), y = (cr[k].y + cr[k + 1].y) / 2; mr.push(M4(V(rr(-.9, .9), y + rr(-.1, .1), rr(-.9, .9)), q, .05)); } g.add(instanced(sphGeo, std('#ffb3c0', { glow: .4 }), mr));
  const c7 = cr[Math.min(7, cr.length - 1)], c4 = cr[Math.min(4, cr.length - 1)], c5 = cr[Math.min(5, cr.length - 1)];
