  const pxM = partModel('peroxisome').group, perox = [];
  for (let i = 0; i < 6; i++) { const p = spot(.3, .45); if (!p) break; const m = pxM.clone(); m.scale.setScalar(.075); m.position.copy(p); m.rotation.set(rr(0, 6.3), rr(0, 6.3), 0); g.add(m); perox.push(p); }
