  const amyM = partModel('amyloplast').group, amy = [];
  for (let i = 0; i < 3; i++) { const p = spot(.5, .7); if (!p) break; const m = amyM.clone(); m.scale.setScalar(.13); m.position.copy(p); m.quaternion.copy(qFromTo(UP, superN(p, AX, BY, BY, 6))); g.add(m); amy.push(p); }
