    const rad = k => { const a = (k * 60 - 60) * Math.PI / 180; return V(Math.cos(a), Math.sin(a), 0); };
    const ring = []; for (let k = 0; k < 6; k++) ring.push(rad(k).multiplyScalar(1.45).add(V(0, 0, k % 2 ? .25 : -.25)));
