  for (const s of [1, -1]) { const er = sphere(1, xray(C.ser, .8, 1.6, .03), 48); er.scale.set(5, .3, 3.5); er.position.y = s * (H / 2 + 3.6); g.add(er); }
  const sm = std('#ffd24f', { glow: .3 }); let spoke = null;
