  const w = molecule([['O', 0, 0, 0], ['H', .76, .59, 0], ['H', -.76, .59, 0]]); w.position.copy(wp); g.add(w);
  const ox = molecule([['O', -.6, 0, 0], ['O', .6, 0, 0]]); ox.position.copy(o2); g.add(ox);
