  for (const y of [-.45, .45]) for (let z = -D / 2 + .6; z < D / 2; z += 1.1) {
    for (let x = -W / 2 + .5, k = 0; x < W / 2; x += .6, k++) { bm.push(M4(V(x, y, z), undefined, .24)); bc.push(k % 2 ? cA : cB); if (k % 3 === 1 && z + 1.1 < D / 2) g.add(stick(V(x, y, z), V(x, y + (y < 0 ? .9 : 0), z + 1.1), .07, pep)); }
  }
