  for (let i = 0; i < 14; i++) { const x = rr(-W / 2 + 1, W / 2 - 1), z = rr(-D / 2 + 1, D / 2 - 1); g.add(stick(V(x, .6, z), V(x, 3.9, z), .06, std('#ff9ad5', { glow: .3 }))); }
