function buildPeptidoglycan() {
  const g = new THREE.Group(), ring = new THREE.CylinderGeometry(.62, .62, .26, 6), nag = std('#9dff7a', { glow: .2 }), nam = std('#4fd1ff', { glow: .2 }), link = std('#dddddd'), cols = ['#ff6b6b', '#ffd24f', '#6bff9e', '#ff9ad5'];
  let pNag = null, pNam = null, pPep = null;
  for (let c = 0; c < 3; c++) {
    const z = (c - 1) * 4.2;
    for (let i = 0; i < 10; i++) {
      const x = (i - 4.5) * 1.55, r = new THREE.Mesh(ring, i % 2 ? nam : nag); r.position.set(x, 0, z); r.rotation.x = Math.PI / 2; g.add(r);
      if (i) g.add(stick(V(x - 1.55 + .62, 0, z), V(x - .62, 0, z), .1, link));
      if (c === 1 && i === 4) pNag = V(x, 0, z + .2); if (c === 1 && i === 5) pNam = V(x, .3, z + .2);
      if (i % 4 === 1 && c < 2) {
        let prev = V(x, -.6, z);
        for (let k = 1; k <= 4; k++) { const p = V(x + (k % 2 ? .35 : -.35), -.9, z + k * .84), s = sphere(.36, std(cols[k - 1], { glow: .25 }), 20); s.position.copy(p); g.add(s, stick(prev, p, .09, link)); prev = p; if (c === 0 && i === 5 && k === 2) pPep = p; }
        g.add(stick(prev, V(x, -.6, z + 4.2), .09, link));
      }
    }
  }
  return finalize(g, [A(pNag, 'NAG sugar', 'glucose'), A(pNam, 'NAM sugar', 'glucose'), A(pPep ?? V(0, -.9, -2), 'Peptide cross-link (amino acids)', 'amino-acid'), A(V(-7, 0, 4.4), 'Glycan strand'), A(V(7, -.9, 2), 'Mesh holds the cell’s shape')]);
}

