  const tipB = blob(1.3, std('#ff7ad9', { glow: .25 }), .2, 1.4); tipB.position.y = 31; g.add(tipB);
  for (const [r, y, c] of [[2.2, -1.6, '#6bc8ff'], [1.8, -3, '#c38cff']]) { const m = new THREE.Mesh(new THREE.TorusGeometry(r, .45, 12, 40), std(c, { glow: .2 })); m.rotation.x = Math.PI / 2; m.position.y = y; g.add(m); }
