    const pp = walk(ribs[2].clone().add(V(0, .9, 0)), 7, .45); pp.forEach(x => { const s = sphere(.2, std(new THREE.Color().setHSL(rand(), .8, .6).getStyle(), { glow: .2 }), 12); s.position.copy(x); g.add(s); }); g.add(tube(pp, .07, std('#9dff7a')));
    units.push({ rnap: p, mrna: m.curve.getPointAt(.25), rib: ribs[1], pep: pp[4] });
