function buildPlasmid() {
  const g = new THREE.Group(), axis = new THREE.CatmullRomCurve3([V(-9, -2.5, 0), V(-5, 2.5, 1.2), V(0, 3.8, -1), V(5, 2.2, 1), V(9, -2.5, 0)]), N = 200, fr = ptFrames(axis, N), r = 1.15, tw = 6.5 * Math.PI * 2, pts = [];
  const at = (i, f, ex = 0) => { const t = i / N, p = axis.getPointAt(t); return p.addScaledVector(axis.getTangentAt(t), ex).addScaledVector(fr.N[i], Math.cos(f) * r).addScaledVector(fr.B[i], Math.sin(f) * r); };
  // a supercoiled circle: the two halves of the ring twist around each other, closed by a loop at each end
  for (let i = 0; i <= N; i++) pts.push(at(i, i / N * tw));
  for (let k = 1; k < 8; k++) pts.push(at(N, tw + k / 8 * Math.PI, Math.sin(k / 8 * Math.PI) * r * 1.4));
  for (let i = N; i >= 0; i--) pts.push(at(i, i / N * tw + Math.PI));
  for (let k = 1; k < 8; k++) pts.push(at(0, Math.PI - k / 8 * Math.PI, -Math.sin(k / 8 * Math.PI) * r * 1.4));
  const c = new THREE.CatmullRomCurve3(pts, true); g.add(dnaOn(c, .34, .09));
  const gene = (t0, t1, col) => { const s = []; for (let i = 0; i <= 40; i++) s.push(c.getPointAt(t0 + (t1 - t0) * i / 40)); g.add(tube(s, .72, xray(col, 1.1, 1.5, .06), 12, 160)); return c.getPointAt((t0 + t1) / 2); };
  const res = gene(.06, .2, '#ff9a5a'), ori = gene(.3, .36, '#9dff7a'), rep = gene(.42, .55, '#c38cff'), mob = gene(.66, .82, '#7fd8ff');
  let repP = null; for (let i = 0; i < 2; i++) { const b = blob(.8, std('#ff7ad9', { glow: .2 }), .2, 1.4, 28); b.position.copy(c.getPointAt(.32 + i * .025)).add(V(0, .6, .6)); g.add(b); repP = b.position.clone(); }
  return finalize(g, [A(c.getPointAt(.92), 'Double-stranded DNA', 'dna'), A(axis.getPointAt(.5), 'Supercoiled (twisted on itself)'), A(res, 'Antibiotic-resistance gene'), A(ori, 'Origin of replication (ori)'),
    A(repP, 'Replication protein', 'protein'), A(rep, 'Replication genes'), A(mob, 'Transfer genes (can move to other bacteria)')]);
}

function buildRibosome70S() {
  const g = new THREE.Group();
  const L = blob(10, xray('#8fb8ff', .9, 2, .02), .12, 1.6, 96); L.scale.set(1.15, .8, .95); L.position.y = 5; g.add(L);
  const S = blob(8.5, xray('#ffd37a', .9, 2, .02), .12, 1.8, 96); S.scale.set(1.1, .55, .8); S.position.y = -6.5; g.add(S);
  const inL = q => (q.x / 8.6) ** 2 + ((q.y - 5) / 6) ** 2 + (q.z / 7.1) ** 2 < 1, inS = q => (q.x / 7) ** 2 + ((q.y + 6.5) / 3.5) ** 2 + (q.z / 5.1) ** 2 < 1;
  // rRNA: many short double-stranded helices packed into each subunit
  let rh = null;
  for (let i = 0; i < 34; i++) {
    const small = i % 3 === 0, test = small ? inS : inL; let c; do { c = V(rr(-9, 9), small ? rr(-10, -3) : rr(0, 10), rr(-7, 7)); } while (!test(c));
    const d = randDir(), l = rr(1.6, 3.2), cv = new THREE.CatmullRomCurve3([c.clone().addScaledVector(d, -l), c.clone().addScaledVector(d, l)]); g.add(dnaAlong(cv, 1.4, .55, .14)); if (!small && (!rh || c.z > rh.z)) rh = c;
  }
  let rp = null;
  for (let i = 0; i < 36; i++) {
    const small = i % 3 === 0, d = randDir(), b = blob(rr(1, 1.7), std(new THREE.Color().setHSL(.5 + rand() * .35, .7, .62).getStyle(), { glow: .15 }), .2, 1.5, 28);
    b.position.copy(small ? V(d.x * 7.6, -6.5 + d.y * 4.4, d.z * 6.4) : V(d.x * 10.8, 5 + d.y * 7.6, d.z * 8.9)); g.add(b); if (!small && d.x < 0 && (!rp || b.position.z > rp.z)) rp = b.position.clone();
  }
  const stalk = [V(-11, 6, 0), V(-15, 9, 1), V(-17, 13, 0)]; g.add(tube(stalk, .5, std('#c38cff'))); stalk.forEach((p, i) => { if (i) { const b = blob(1, std('#c38cff', { glow: .2 }), .2, 1.4, 20); b.position.copy(p); g.add(b); } });
  const mp = []; for (let x = -26; x <= 26; x += 2) mp.push(V(x, -2.4 + Math.sin(x * .3) * .4, 3)); const m = rnaThread(mp, .4); g.add(m.group);
  const tr = [];
  [['#ff6fd8', -5.5, 'E'], ['#c07cff', 0, 'P'], ['#6fffd8', 5.5, 'A']].forEach(([c, x]) => { const pts = [V(x, -1.5, 3), V(x, 3, 2.4), V(x + .5, 4.6, 1.4), V(x + 4, 4.9, .2)]; g.add(tube(pts, .7, std(c, { glow: .25 }))); const lp = new THREE.Mesh(new THREE.TorusGeometry(.9, .3, 8, 20), std(c, { glow: .25 })); lp.position.set(x, -1.6, 3); g.add(lp); tr.push(pts[1]); });
  const pp = [V(4, 5, 0), V(1.3, 9, -.5), V(.8, 13.5, 0), V(2, 16, 1), V(4, 17.5, 0), V(6, 19, 2), V(5, 21, 4)]; g.add(tube(pp, .35, std('#9dff7a')));
  pp.slice(3).forEach((p, i) => { const s = sphere(.75, std(new THREE.Color().setHSL(i * .2, .8, .6).getStyle(), { glow: .2 })); s.position.copy(p); g.add(s); });
  return finalize(g, [A(V(-9, 9, 6), 'Large subunit (50S)', 'ribo-50s'), A(V(-8, -8.5, 5), 'Small subunit (30S)', 'ribo-30s'), A(rh, 'rRNA helix', 'rna'), A(rp, 'Ribosomal protein', 'protein'),
    A(V(-22, -2.4, 3), 'mRNA', 'rna'), A(tr[2], 'tRNA in A site', 'trna'), A(tr[1], 'P site'), A(tr[0], 'E site (exit)'), A(pp.at(-1), 'Growing polypeptide', 'polypeptide'), A(stalk[2], 'L7/L12 stalk'), A(V(1.2, 11, 0), 'Exit tunnel')]);
}

function buildTRNA() {
  const g = new THREE.Group();
  // an upside-down L: acceptor/T arm across the top, D/anticodon arm down the side
  g.add(dnaAlong(new THREE.CatmullRomCurve3([V(-1, 8, 0), V(9, 8, 0)]), 3, 1, .26), dnaAlong(new THREE.CatmullRomCurve3([V(0, 9, 0), V(0, -3, 0)]), 3.5, 1, .26));
  const loop = (c, r, col) => { const t = new THREE.Mesh(new THREE.TorusGeometry(r, .32, 10, 32), std(col, { glow: .25 })); t.position.copy(c); g.add(t); return c; };
  const ac = loop(V(0, -4.6, 0), 1.6, '#ffb35c'), dl = loop(V(-2.3, 4.5, 0), 1.1, '#ff9ad5'), tl = loop(V(5.5, 10.2, 0), 1.1, '#9dff7a');
  ['C', 'A', 'U'].forEach((b, i) => { const x = (i - 1) * 1.1, p = V(x, -6.1, 0), q = V(x, -7.8, 0); g.add(stick(p, q, .38, std(BASE[b], { glow: .3 }))); });
  const cca = [V(9.5, 8, 0), V(10.4, 8.9, 0), V(11.2, 9.8, 0), V(12, 10.7, 0)]; cca.slice(1).forEach((p, i) => { const s = sphere(.55, std(BASE['CCA'[i]], { glow: .25 })); s.position.copy(p); g.add(s, stick(cca[i], p, .2, std('#dddddd'))); });
  nest(g, buildAmino(), V(14.2, 12.4, 0), .75);
  return finalize(g, [A(V(0, -7, .4), 'Anticodon (pairs with a codon)'), A(V(4, 8, 1), 'Acceptor stem'), A(cca[2], 'CCA end'), A(V(14.2, 12.4, .5), 'Amino acid (carried cargo)', 'amino-acid'),
    A(dl, 'D loop'), A(tl, 'T loop'), A(V(0, 2, 1), 'Nucleotide', 'nucleotide')]);
}

