  const sg = blob(2.4, std('#ffd24f', { glow: .2 }), .2, 1.4, 40); sg.scale.set(1.3, .8, .9); sg.position.set(-7.5, 6, 3.5); g.add(sg);
  for (const x of [-2, 2]) { const a = blob(2, std('#6bc8ff', { glow: .15 }), .2, 1.4, 32); a.position.set(x, 0, -8); g.add(a); }
