  return finalize(g, [A(V(-16, 0, .9), 'Template DNA', 'dna'), A(V(0, 2.3, .9), 'Transcription bubble'), A(m.curve.getPointAt(.65), 'mRNA leaving', 'rna'), A(V(4, 9, 3.5), 'β′ pincer', 'protein'),
    A(V(4, -9, 3.5), 'β pincer', 'protein'), A(sg.position, 'σ factor (finds the start of a gene)'), A(mg.position, 'Active site (Mg²⁺)'), A(V(0, 0, -10), 'α subunits'), A(V(18, 1.5, 1), 'Downstream DNA')]);
