    const a = k / 3 * Math.PI * 2 + .4, lp = V(.58 * Math.cos(a), -.55, .58 * Math.sin(a));
    const ly = blob(.36, std('#7dffb2', { glow: .28 }), .15, 1.5, 18); ly.position.copy(lp); g.add(ly);
