  an.push(A(V(2.1, 1.5, 1.2), 'Collar & fibritin whiskers (gpWac)', 'phage-tail'),
    A(V(-1.0, -1.6, .9), 'Contractile tail sheath (gp18) & inner tube (gp19)', 'phage-tail'));
