  // Three layered protein plaques of the yeast SPB
  const op = new THREE.Mesh(new THREE.CylinderGeometry(3.2, 3.2, .75, 48), std('#ffb84d', { glow: .35 })); op.position.y = 2.6; op.userData.part = 'protein'; g.add(op);
  const cp = new THREE.Mesh(new THREE.CylinderGeometry(3.5, 3.5, .95, 48), std('#ff7a52', { glow: .35 })); cp.position.y = 0; cp.userData.part = 'protein'; g.add(cp);
  const ip = new THREE.Mesh(new THREE.CylinderGeometry(3.0, 3.0, .75, 48), std('#ffd966', { glow: .35 })); ip.position.y = -2.5; ip.userData.part = 'protein'; g.add(ip);
  // Half-bridge (Sfi1 / Kar1 / Cdc31) extending along the nuclear envelope for SPB duplication
  const hb = new THREE.Mesh(new THREE.BoxGeometry(3.6, .55, 2.2), std('#ff9ad5', { glow: .3 })); hb.position.set(5.1, .2, 0); hb.userData.part = 'protein'; g.add(hb);
  // Cytoplasmic astral microtubules (upward) and intranuclear spindle microtubules (downward, closed mitosis)
  const mtMat = std('#88d8ff', { glow: .35 }), tupMat = std('#c88cff', { glow: .4 });
  for (let k = 0; k < 3; k++) {
    const a = (k / 3) * Math.PI * 2 + .4, b = V(1.6 * Math.cos(a), 3.1, 1.6 * Math.sin(a)), tip = V(4.2 * Math.cos(a), 9.2, 4.2 * Math.sin(a));
    const gt = sphere(.42, tupMat, 16); gt.position.copy(b); g.add(gt);
    const m = stick(b, tip, .26, mtMat); m.userData.part = 'microtubule'; g.add(m);
  }
  for (let k = 0; k < 7; k++) {
    const a = (k / 7) * Math.PI * 2, b = V((k === 0 ? 0 : 1.9 * Math.cos(a)), -3.0, (k === 0 ? 0 : 1.9 * Math.sin(a))), tip = V((k === 0 ? 0 : 2.8 * Math.cos(a)), -9.6, (k === 0 ? 0 : 2.8 * Math.sin(a)));
    const gt = sphere(.38, tupMat, 16); gt.position.copy(b); g.add(gt);
    const m = stick(b, tip, .25, mtMat); m.userData.part = 'microtubule'; g.add(m);
  }
