function buildErgosterol() {
  // Four fused steroid rings (A, B with conjugated Δ5,7 double bonds, C, D) + 3β-OH + C22-unsaturated C24-methyl tail
  const ring = (cx, cy, r, n, a0 = 0) => Array.from({ length: n }, (_, k) => V(cx + r * Math.cos(a0 + k * 2 * Math.PI / n), cy + r * Math.sin(a0 + k * 2 * Math.PI / n), (k % 2 ? .16 : -.16)));
  const rA = ring(-3.6, -.4, 1.4, 6), rB = ring(-1.2, -.4, 1.4, 6), rC = ring(1.2, .75, 1.4, 6), rD = ring(3.4, .55, 1.2, 5, .2);
  const pts = [...rA, rB[1], rB[2], rB[4], rB[5], rC[0], rC[1], rC[2], rC[5], rD[0], rD[1], rD[4]];
  const tail = []; for (let i = 0; i < 6; i++) tail.push(V(4.6 + i * 1.15, 1.1 + (i % 2) * .65, (i % 2 ? -.2 : .2)));
  const me1 = V(-2.4, .9, 1.15), me2 = V(2.3, 1.8, 1.15), me24 = tail[3].clone().add(V(.2, 1.15, .8));
  pts.push(...tail, me1, me2, me24);
  const atoms = pts.map(p => ['C', p.x, p.y, p.z]);
  atoms.push(['O', -5.2, -1.1, 0], ['H', -5.95, -.55, 0]);
  const m = molecule(atoms), P = m.userData.P;
  return finalize(m, [A(P[atoms.length - 2], '3β-hydroxyl group (–OH): polar head facing membrane surface', 'atom-o'),
    A(V(-1.2, -.4, .2), 'Steroid B-ring (conjugated Δ5,7 double bonds — UV converts to vitamin D₂)', 'atom-c'),
    A(tail[2], 'Unsaturated side chain (Δ22 double bond & C24 methyl group)', 'atom-c'),
    A(me1, 'Angular methyl group (removed by Erg11 during synthesis)', 'atom-c'),
    A(P[atoms.length - 1], 'Hydrogen', 'atom-h')]);
}
